import React from "react";
import { useSelector } from "react-redux";
import "./Home.css";

const HomeContent = () => {
  const user = useSelector((state) => state.intern.user) || JSON.parse(localStorage.getItem("user"));

  if (!user) {
    return <h2 className="title">No user found. Please sign up first.</h2>;
  }

  return (
    <div className="details-box">
      <h2 className="title">🎓 Taizo Interns 🎓</h2>
      <div className="info-row">
        <span className="label">Name:</span>
        <span className="value">{user.name}</span>
      </div>
      <div className="info-row">
        <span className="label">Intern Type:</span>
        <span className="value">{user.internType}</span>
      </div>
      <div className="info-row">
        <span className="label">Duration:</span>
        <span className="value">{user.duration}</span>
      </div>
      <div className="info-row">
        <span className="label">Result:</span>
        <span className="value selected">✅ Selected</span>
      </div>
    </div>
  );
};

export default HomeContent;
